    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endRSD(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // RSD_ID
        $builder->required($o, 40);  // RANGE_M
        $builder->required($o, 42);  // DETECTION_PROBABILITY
        $builder->required($o, 44);  // FALSE_ALARM_PROBABILITY
        $builder->required($o, 46);  // SNR_DB
        $builder->required($o, 64);  // PROVENANCE
        $builder->required($o, 68);  // PRODUCER_ID
        $builder->required($o, 70);  // SIGNATURE
        $builder->required($o, 72);  // CANONICAL_JSON_SIGNATURE
        return $o;
    }

    public static function finishRSDBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, "$RSD");
    }
